export async function ci_failure(context, params) {
    try {
        const evidence = await context.getFailureEvidence(params.runId, params);
        if (!evidence) {
            return JSON.stringify({
                runId: params.runId,
                found: false,
                message: 'No failure evidence found for this run.',
            });
        }
        return JSON.stringify({
            runId: params.runId,
            found: true,
            summary: evidence.summary,
            errorClass: evidence.errorClass,
            confidence: evidence.confidence,
            totalFailures: evidence.totalFailures,
            sourceReferences: evidence.sourceReferences.slice(0, 20),
            logExcerpts: evidence.logExcerpts.map(e => ({
                label: e.label,
                text: e.text.slice(0, 4000),
                errorCategory: e.errorCategory,
            })),
            diagnostics: evidence.diagnostics,
        });
    }
    catch (error) {
        return JSON.stringify({
            runId: params.runId,
            error: error instanceof Error ? error.message : 'Unknown error',
        });
    }
}
